sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float4 screen;
uniform float2 layer;
uniform float2 acLayerCenterNorm;
uniform float2 acScreenSize;
uniform float frequency;
uniform float strength;
uniform float phase;
uniform float radius;
uniform float feather;
uniform float2 center;
float2 AcScreenNorm(float2 p) { return (p - screen.xy) / max(screen.zw, float2(1.0)); }
half4 main(float2 coord) {
    float2 st = AcScreenNorm(coord);
    float2 c = center / 1000.0 * float2(-1.0, 1.0);
    float featherSize = radius * 0.5 * feather;
    float innerRadius = max(0.0, radius - featherSize);
    float outerRadius = max(innerRadius + 0.00001, radius + featherSize);
    st -= acLayerCenterNorm - c;
    st.y *= acScreenSize.y / acScreenSize.x;
    float dist = length(st);
    float damping = smoothstep(outerRadius, innerRadius, dist);
    float2 dir = dist > 0.000001 ? st / dist : float2(0.0);
    float2 shift = sin(dist * frequency * 6.2831853 + phase * 6.2831853) * strength * 0.5 * dir * damping;
    st += shift;
    st.y /= acScreenSize.y / acScreenSize.x;
    st += acLayerCenterNorm - c;
    return image.eval(st * screen.zw + screen.xy);
}
